mapper.select:
SELECT STAFF.ID, BADGE, STAFF.NAME, STAFF.DEP_ABBR, COMP_NAME, DEP_NAME, JCHE_NAME, JOB_NAME, STAFF.CREATE_TIME, STATUS ,DORMITORY_STATUS, STAFF.certno, STAFF.face_pic_id, STAFF.comp_id FROM SMT_STAFF STAFF
NAME LIKE CONCAT(CONCAT('%',#{query.name}),'%')
AND BADGE LIKE CONCAT(CONCAT('%',#{query.badge}),'%')
AND BADGE in
#{item}
AND PHONE LIKE CONCAT(CONCAT('%',#{query.phone}),'%')
AND COMP_ID =#{query.compId}
AND DEP_ID =#{query.depId}
AND JOB_ID =#{query.jobId}
AND JOB_NAME LIKE CONCAT(CONCAT('%',#{query.jobName}),'%')
AND DEP_ABBR LIKE CONCAT(CONCAT('%',#{query.depAbbr}),'%')
AND JCHE_ID =#{query.jcheId}
AND STATUS =#{query.status}
AND STAFF.face_pic_id is null
AND STAFF.face_pic_id is not null
AND STAFF.CREATE_TIME between to_date(#{query.startTime},'yyyy-mm-dd hh24:mi:ss') and to_date(#{query.endTime},'yyyy-mm-dd hh24:mi:ss')
AND STAFF.COMP_ID is not null AND ( STAFF.COMP_ID in ( select DISTINCT bu.COMP_ID from SMT_PARK_BU bu
AND bu.park_id =#{query.parkId}
AND bu.park_id in
#{item}
) or STAFF.COMP_ID in ( select DISTINCT bu.ID from smt_organize_relation bu
AND bu.park_id =#{query.parkId}
AND bu.park_id in
#{item}
) )
ORDER BY CREATE_TIME DESC,STAFF.NAME ASC

SELECT STAFF.ID STAFF_ID, STAFF.BADGE, STAFF.NAME, STAFF.DEP_ABBR, STAFF.COMP_NAME, STAFF.DEP_NAME, STAFF.JCHE_NAME, STAFF.JOB_NAME, STAFF.CREATE_TIME, STAFF.STATUS, STAFF.DORMITORY_STATUS, STAFF.CERTNO, STAFF.FACE_PIC_ID, STAFF.COMP_ID FROM SMT_STAFF STAFF
AND STAFF.NAME LIKE CONCAT(CONCAT('%',#{query.staffName}),'%')
AND STAFF.BADGE LIKE CONCAT(CONCAT('%',#{query.staffBadge}),'%')
AND STAFF.COMP_ID in
#{item}
AND STAFF.BADGE in
#{item}
AND STAFF.DEP_ID in
#{item}
AND STAFF.COMP_ID = #{query.buId}
AND STAFF.DEP_ID = #{query.depId}
AND STAFF.CREATE_TIME BETWEEN to_date(#{query.startDate},'yyyy-MM-dd hh24:mi:ss') AND to_date(#{query.endDate},'yyyy-MM-dd hh24:mi:ss')
AND STAFF.ID IN (SELECT STAFF_ID FROM SMT_SECURITY_PERSON_RELATION)
AND STAFF.ID NOT IN (SELECT STAFF_ID FROM SMT_SECURITY_PERSON_RELATION)
AND STAFF.COMP_ID IS NOT NULL AND ( STAFF.COMP_ID in ( select DISTINCT bu.COMP_ID from SMT_PARK_BU bu
AND bu.park_id =#{query.parkId}
AND bu.park_id in
#{item}
) or STAFF.COMP_ID in ( select DISTINCT bu.ID from smt_organize_relation bu
AND bu.park_id =#{query.parkId}
AND bu.park_id in
#{item}
) )
ORDER BY STAFF.CREATE_TIME DESC,STAFF.NAME ASC

SELECT DORMITORY_NAME DORMITORYNAME, FLOOR_NAME FLOORNAME, DS.ROOM_NAME ROOMNAME, BED_NUMBER BEDNUMBER, ROOM_ID ROOMID, SR.FLOOR_ID FLOORID, SR.PARK_ID PARKID, SR.BED_TOTAL BEDTOTAL, PARK.PARK_NAME PARKNAME, SR.DORMITORY_ID FROM SMT_DORMITORY_STAFF DS LEFT JOIN SMT_DORMITORY_ROOM SR ON DS.ROOM_ID = SR. ID INNER JOIN SMT_PARK PARK ON SR.PARK_ID = PARK.ID
AND DS.STAFF_BADGE=#{badge}
AND DS.STAFF_ID=#{badge}

SELECT STAFF.ID, STAFF.NAME,STAFF.BADGE,COMP_NAME,COMP_ID,DEP_NAME,STAFF.WELFARE_LEVEL,
JCHE_NAME,JOB_NAME,STAFF.certno,STAFF.CREATE_TIME from SMT_STAFF STAFF

WHERE

STAFF.STATUS <> #{query.status}


	AND STAFF.COMP_ID =#{query.compId}


	AND STAFF.DEP_ID =#{query.depId}


	AND STAFF.JOB_ID =#{query.jobId}



	AND STAFF.NAME LIKE CONCAT(CONCAT('%',#{query.name}),'%')


	AND STAFF.BADGE LIKE CONCAT(CONCAT('%',#{query.badge}),'%')

and
(
STAFF.COMP_ID in (
select DISTINCT bu.COMP_ID from SMT_PARK_BU bu


		AND bu.park_id =#{query.parkId}


		AND bu.park_id in

			#{item}



)
or
STAFF.COMP_ID in (
select DISTINCT bu.ID from smt_organize_relation bu


		AND bu.park_id =#{query.parkId}


		AND bu.park_id in

			#{item}



)
)
ORDER BY CREATE_TIME DESC
